pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Initialize the contract
        c.initialize(address(this));

        // Deploy a proxy that delegatecalls to c
        address proxy = address(new Proxy(c));

        // Call proxiableUUID via delegatecall on the proxy
        // In the reference, this should return IMPLEMENTATION_SLOT
        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        bytes32 result = Proxy(proxy).proxiableUUIDFromC();
        assertTrue(result == expected, "proxiableUUID() should return IMPLEMENTATION_SLOT");
    }
}

contract Proxy {
    address public implementation;

    constructor(address _impl) {
        implementation = _impl;
    }

    function proxiableUUIDFromC() external view returns (bytes32) {
        (bool success, bytes memory data) = implementation.staticcall(
            abi.encodeWithSignature("proxiableUUID()")
        );
        require(success, "call failed");
        return abi.decode(data, (bytes32));
    }
}

