import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(address _vault, address _asset, uint256 _timestamp) public {
        // Bound the timestamp so that it's realistic: between 0 and 2^48 (≈8.9 years)
        vm.assume(_timestamp < 2**48);

        // First initialize
        c.initialize(address(0x1234));

        // Set the block timestamp
        vm.warp(_timestamp);

        // Call rate; it should not revert (the test will fail if it reverts)
        // We capture the return value
        uint256 rateResult = c.rate(_vault, _asset);

        // The general rule: when block.timestamp == utilizationData.lastUpdate (reference's branch vs mutant's branch difference),
        // the returned rate must be consistent. Since we cannot directly read internal storage, we assert that the function
        // always returns a value (does not revert) and that the returned value is within a reasonable range.
        // For the specific mutation (changing > to >=), the difference only manifests when block.timestamp == utilizationData.lastUpdate.
        // In that case, the reference contract takes the first branch (since timestamp > lastUpdate is false),
        // while the mutant takes the first branch too (since >= is true). Both branches compute utilization differently:
        // reference: uses IVault.utilization (since elapsed != block.timestamp is false due to elapsed=0)
        // mutant: also uses IVault.utilization (since elapsed=0, elapsed != timestamp is true, so it computes (index - index)/0 which would revert on division by zero)
        // Wait, careful: when elapsed == 0, elapsed != timestamp is true (0 != timestamp), so mutant tries to do division by zero -> revert.
        // So the mutant reverts when elapsed == 0. That's the bug.
        // Thus the rule: rate should never revert when block.timestamp == utilizationData.lastUpdate.
        // But we cannot read lastUpdate externally. So we must test a stronger property: rate never reverts.
        // However, the reference does revert in some cases (e.g., if the vault address is invalid). We need a different approach.
        // Let's check the exact condition: when timestamp == lastUpdate, reference takes else branch (uses IVault.utilization),
        // mutant takes if branch, and then if elapsed != timestamp (true), it tries to divide by zero -> revert.
        // So the mutant reverts while reference does not. But we can't set lastUpdate directly.
        // We can only test after a first call that sets lastUpdate. So we do two calls: first sets lastUpdate, second with same timestamp triggers bug.

        // Actually, let's redesign: we call rate twice, the second at the same timestamp.
        // First, ensure a call that sets lastUpdate:
        c.rate(_vault, _asset); // this sets utilizationData.lastUpdate = block.timestamp

        // Now call again at the same timestamp:
        bool reverted;
        try c.rate(_vault, _asset) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: the second call should NOT revert (since the reference does not revert)
        assertTrue(!reverted, "Rate should not revert when called twice at same timestamp");
    }
}

